-- 김충익
update faculty set
  bio_ko = $q$<h3>학력</h3><ul><li>서울대학교 이학사 (2003)</li><li>Northwestern University 이학박사 (2009)</li></ul><h3>경력</h3><ul><li>서강대학교 화공생명공학과 교수 (2011–현재)</li><li>하버드대학교 박사후연구원 (2009–2010)</li></ul><h3>주요 논문</h3><ul><li>D. Ganesan, H. Kim, Y-Q. Li, J. Noh, W-Y. Chen, S-H. Hong, C-L. Liu, M-C. Chen, C. Kim, "Pentafluorophenyl End-Capped Bithiophene Imide (BTI) based n-Type Semiconductors for Organic Thin-Film Transistors," <em>J. Mater. Chem. C</em> 14, 4943-4952 (2026)</li><li>S. Oh, H. Kim, J. Oh, H. Kim, S. Kim, H. Cho, C. Kim, "Enhancing Proton Irradiation Tolerance of a-IGZO Thin-Film Transistors through Hydrogen Doping," <em>J. Mater. Chem. C</em> 14, 3637-3647 (2026)</li><li>H. Do, H. You, H. Kim, S. Kim, D. Ho*, S. Kim*, C. Kim*, "Improved AC Drain Bias Stability in InZnO TFTs with an Hf-Doped Heterobilayer Structure," <em>ACS Appl. Mater. Interfaces</em> 17, 40662-40672 (2025)</li><li>J. Kim, S. Kim, H. Kim, D. Ho*, S. Kim*, C. Kim*, "Enhancing AC Stress Stability of Indium Gallium Zinc Oxide Thin-Film Transistors via Controlled Hydrogen Diffusion," <em>J. Mater. Chem. C</em> 13, 3587-3594 (2025)</li><li>D. Ho, H. Jeong, H. B. Park, S. K. Park, M.-G. Kim, C. Kim*, "Solution-Processed Amorphous Zinc Indium Tin Oxide Thin-Film Transistors with High AC Stress Stability," <em>J. Mater. Chem. C</em> 11, 13395-13402 (2023)</li><li>D. Ho, S. Choi, H. Kang, B. Park, S. K. Park, M.-G. Kim*, C. Kim*, A. Facchetti, "In-Situ Radiation Hardness Study of Amorphous Zn-In-Sn-O Thin-Film Transistors with Structural Plasticity and Defect Tolerance," <em>ACS Appl. Mater. Interfaces</em> 15, 33751-33762 (2023)</li></ul>$q$,
  bio_en = $q$<h3>Education</h3><ul><li>B.S., Seoul National University (2003)</li><li>Ph.D., Northwestern University (2009)</li></ul><h3>Experience</h3><ul><li>Professor, Department of Chemical and Biomolecular Engineering, Sogang University (2011–present)</li><li>Postdoctoral Researcher, Harvard University (2009–2010)</li></ul><h3>Selected Publications</h3><ul><li>D. Ganesan, H. Kim, Y-Q. Li, J. Noh, W-Y. Chen, S-H. Hong, C-L. Liu, M-C. Chen, C. Kim, "Pentafluorophenyl End-Capped Bithiophene Imide (BTI) based n-Type Semiconductors for Organic Thin-Film Transistors," <em>J. Mater. Chem. C</em> 14, 4943-4952 (2026)</li><li>S. Oh, H. Kim, J. Oh, H. Kim, S. Kim, H. Cho, C. Kim, "Enhancing Proton Irradiation Tolerance of a-IGZO Thin-Film Transistors through Hydrogen Doping," <em>J. Mater. Chem. C</em> 14, 3637-3647 (2026)</li><li>H. Do, H. You, H. Kim, S. Kim, D. Ho*, S. Kim*, C. Kim*, "Improved AC Drain Bias Stability in InZnO TFTs with an Hf-Doped Heterobilayer Structure," <em>ACS Appl. Mater. Interfaces</em> 17, 40662-40672 (2025)</li><li>J. Kim, S. Kim, H. Kim, D. Ho*, S. Kim*, C. Kim*, "Enhancing AC Stress Stability of Indium Gallium Zinc Oxide Thin-Film Transistors via Controlled Hydrogen Diffusion," <em>J. Mater. Chem. C</em> 13, 3587-3594 (2025)</li><li>D. Ho, H. Jeong, H. B. Park, S. K. Park, M.-G. Kim, C. Kim*, "Solution-Processed Amorphous Zinc Indium Tin Oxide Thin-Film Transistors with High AC Stress Stability," <em>J. Mater. Chem. C</em> 11, 13395-13402 (2023)</li><li>D. Ho, S. Choi, H. Kang, B. Park, S. K. Park, M.-G. Kim*, C. Kim*, A. Facchetti, "In-Situ Radiation Hardness Study of Amorphous Zn-In-Sn-O Thin-Film Transistors with Structural Plasticity and Defect Tolerance," <em>ACS Appl. Mater. Interfaces</em> 15, 33751-33762 (2023)</li></ul>$q$,
  research_ko = $q$<p>STRESS-RESISTANT ELECTRONIC MATERIALS AND DEVICES<br>New radiation- or bias-stress resistant materials including metal oxides and organic/inorganic hybrids for mission- or safe-critical applications (e.g. nano-scaled semiconductor circuits, space exploration, nuclear energy, and medical technology).</p><p>GREEN PROCESS FOR ORGANIC OPTOELECTRONIC DEVICES<br>Green (eco-friendly) materials and processes for the fabrication of organic optoelectronic devices. Exploration of a wide range of green solvents to process organic semiconductor layers for enhanced electrical performance and stability.</p><p>RECYCLING OF END-OF-LIFE SOLAR PANELS<br>Synthesis of silica/silicon nanoparticles from end-of-life solar panels for application as anode materials in lithium ion batteries.</p>$q$,
  research_en = $q$<p>STRESS-RESISTANT ELECTRONIC MATERIALS AND DEVICES<br>New radiation- or bias-stress resistant materials including metal oxides and organic/inorganic hybrids for mission- or safe-critical applications (e.g. nano-scaled semiconductor circuits, space exploration, nuclear energy, and medical technology).</p><p>GREEN PROCESS FOR ORGANIC OPTOELECTRONIC DEVICES<br>Green (eco-friendly) materials and processes for the fabrication of organic optoelectronic devices. Exploration of a wide range of green solvents to process organic semiconductor layers for enhanced electrical performance and stability.</p><p>RECYCLING OF END-OF-LIFE SOLAR PANELS<br>Synthesis of silica/silicon nanoparticles from end-of-life solar panels for application as anode materials in lithium ion batteries.</p>$q$,
  keywords = $q$Organic/Inorganic Hybrid Electronics, Optoelectronic Devices, Green Process, Solar Panel Recycling$q$
where name_ko = '김충익';

