update faculty set
  bio_ko = $q$<h3>학력</h3><ul><li>KAIST 이학사 (2007)</li><li>KAIST 이학박사 (2012)</li></ul><h3>경력</h3><ul><li>책임연구원 (한국화학연구원, 2014–2022)</li><li>겸직교수 (포항공대, 2020–2022)</li><li>부교수 (과학기술연합대학원대학교, 2016–2022)</li><li>연구원 (SK이노베이션, 2012–2014)</li></ul><h3>주요 수상</h3><ul><li>서강대학교 총동문회 서강알바트로스 학술상 (2025)</li><li>한국고분자학회 고분자학술진보상 (2024)</li><li>제1회 에코프로 젊은 과학자상(EYSA) 환경부문 (2023)</li><li>대한화학회 고분자화학분과 TCI 신진학술상 (2023)</li></ul><h3>학회 활동</h3><ul><li>한국고분자학회 학술위원회 위원 (2024)</li><li>한국고분자학회 에코소재 분과 임원 (2023–2024)</li><li>대한화학회 고분자화학분과회 기획간사 (2022)</li></ul><h3>주요 논문</h3><ul><li>Jeongsik E. Park, Sungbin Ju, Dongyeop X. Oh*, and Jeyoung Park*, "Paradigm-shifting carbon capture with high efficiency and net-negativity through bio-inspired oceanic mineralization," <em>Journal of Materials Chemistry A</em> 14, 34751 (2026) <a href="https://doi.org/10.1039/d6ta03540j">doi.org/10.1039/d6ta03540j</a></li><li>Junhyeok Lee, Haemin Kim, Giyoung Shin, Chaenyung Cha, Dongyeop X. Oh*, and Jeyoung Park*, "Superior pseudo-vitrimer: A high-performance bio-based polyurethane with self-healing and chemical recyclability via Diels–Alder chemistry," <em>Chemical Engineering Journal</em> 535, 175193 (2026) <a href="https://doi.org/10.1016/j.cej.2026.175193">doi.org/10.1016/j.cej.2026.175193</a></li><li>Sebin Jin, Dongyeop X. Oh*, and Jeyoung Park*, "In-use robust and self-healing, on-demand multi-pathway degradations: Bio-based poly(urethane-urea) elastomers with disulfide bonds," <em>Chemical Engineering Journal</em> 528, 172098 (2026) <a href="https://doi.org/10.1016/j.cej.2025.172098">doi.org/10.1016/j.cej.2025.172098</a></li><li>Mira Shin, Minjin Kim, Giyoung Shin, Sung Bae Park, Hyeonyeol Jeon, Dongyeop X. Oh*, Jun Mo Koo*, Wangyun Won*, and Jeyoung Park*, "One-Pot Upcycling of Heterogeneous Polyester Waste to Biodegradable Thermoplastics: A Cost-Effective Solution for a Circular Economy," <em>SusMat</em> 5, e70046 (2025) <a href="https://doi.org/10.1002/sus2.70046">doi.org/10.1002/sus2.70046</a></li><li>Seul-A Park, Hyeonyeol Jeon, Hojung Kwak, Jun Mo Koo, Dongyeop X. Oh*, and Jeyoung Park*, "High-performance transparent polysulfone nanocomposites enhanced with masterbatch-based aramid nanofibers for improved toughness and flame retardancy," <em>Advanced Composites and Hybrid Materials</em> 8, 307 (2025) <a href="https://doi.org/10.1007/s42114-025-01392-0">doi.org/10.1007/s42114-025-01392-0</a></li><li>Sung Bae Park, Hojung Kwak, Dohoon Lee, Giyoung Shin, Min Jang, Hyuni Jung, Hyeonyeol Jeon*, Hyo Jeong Kim*, Jeyoung Park*, and Dongyeop X. Oh*, "Development of Marine-Degradable Poly(Ester Amide)s with Strong, Up-Scalable, and Up-Cyclable Performance," <em>Advanced Materials</em> 37, 2417266 (2025) <a href="https://doi.org/10.1002/adma.202417266">doi.org/10.1002/adma.202417266</a></li><li>Lam Tan Hao, Sungbin Ju, Dong Ki Hwang, Dong Soo Hwang, Yong Sik Ok, Sung Yeon Hwang, Hyo Jeong Kim, Hyeonyeol Jeon*, Jeyoung Park*, Dongyeop X. Oh*, and Jun Mo Koo*, "Optimizing bioplastics translation," <em>Nature Reviews Bioengineering</em> 2, 289-304 (2024) <a href="https://doi.org/10.1038/s44222-023-00142-5">doi.org/10.1038/s44222-023-00142-5</a></li><li>Minkyung Lee, Hojung Kwak, Youngho Eom, Seul-A Park, Takamasa Sakai, Hyeonyeol Jeon, Jun Mo Koo, Dowan Kim, Chaenyung Cha, Sung Yeon Hwang*, Jeyoung Park*, and Dongyeop X. Oh*, "Network of cyano-p-aramid nanofibres creates ultrastiff and water-rich hydrospongels," <em>Nature Materials</em> 23, 414 (2024) <a href="https://doi.org/10.1038/s41563-023-01760-5">doi.org/10.1038/s41563-023-01760-5</a></li><li>Seon-Mi Kim, Hyeonyeol Jeon, Sung-Ho Shin, Seul-A Park, Jonggeon Jegal, Sung Yeon Hwang*, Dongyeop X. Oh*, and Jeyoung Park*, "Superior toughness and fast self-healing at room temperature engineered by transparent elastomers," <em>Advanced Materials</em> 30, 1705145 (2018) <a href="https://doi.org/10.1002/adma.201705145">doi.org/10.1002/adma.201705145</a></li></ul>$q$,
  bio_en = $q$<h3>Education</h3><ul><li>B.S., KAIST (2007)</li><li>Ph.D., KAIST (2012)</li></ul><h3>Experience</h3><ul><li>Principal Researcher, Korea Research Institute of Chemical Technology (2014–2022)</li><li>Adjunct Professor, POSTECH (2020–2022)</li><li>Associate Professor, University of Science and Technology (UST) (2016–2022)</li><li>Researcher, SK Innovation (2012–2014)</li></ul><h3>Selected Awards</h3><ul><li>Sogang Albatross Academic Award, Sogang University Alumni Association (2025)</li><li>Polymer Academic Progress Award, The Polymer Society of Korea (2024)</li><li>The 1st EcoPro Young Scientist Award (EYSA), Environment (2023)</li><li>TCI Young Scientist Award, Division of Polymer Chemistry, Korean Chemical Society (2023)</li></ul><h3>Professional Service</h3><ul><li>Member, Academic Committee, The Polymer Society of Korea (2024)</li><li>Executive Member, Eco-Materials Division, The Polymer Society of Korea (2023–2024)</li><li>Planning Secretary, Division of Polymer Chemistry, Korean Chemical Society (2022)</li></ul><h3>Selected Publications</h3><ul><li>Jeongsik E. Park, Sungbin Ju, Dongyeop X. Oh*, and Jeyoung Park*, "Paradigm-shifting carbon capture with high efficiency and net-negativity through bio-inspired oceanic mineralization," <em>Journal of Materials Chemistry A</em> 14, 34751 (2026) <a href="https://doi.org/10.1039/d6ta03540j">doi.org/10.1039/d6ta03540j</a></li><li>Junhyeok Lee, Haemin Kim, Giyoung Shin, Chaenyung Cha, Dongyeop X. Oh*, and Jeyoung Park*, "Superior pseudo-vitrimer: A high-performance bio-based polyurethane with self-healing and chemical recyclability via Diels–Alder chemistry," <em>Chemical Engineering Journal</em> 535, 175193 (2026) <a href="https://doi.org/10.1016/j.cej.2026.175193">doi.org/10.1016/j.cej.2026.175193</a></li><li>Sebin Jin, Dongyeop X. Oh*, and Jeyoung Park*, "In-use robust and self-healing, on-demand multi-pathway degradations: Bio-based poly(urethane-urea) elastomers with disulfide bonds," <em>Chemical Engineering Journal</em> 528, 172098 (2026) <a href="https://doi.org/10.1016/j.cej.2025.172098">doi.org/10.1016/j.cej.2025.172098</a></li><li>Mira Shin, Minjin Kim, Giyoung Shin, Sung Bae Park, Hyeonyeol Jeon, Dongyeop X. Oh*, Jun Mo Koo*, Wangyun Won*, and Jeyoung Park*, "One-Pot Upcycling of Heterogeneous Polyester Waste to Biodegradable Thermoplastics: A Cost-Effective Solution for a Circular Economy," <em>SusMat</em> 5, e70046 (2025) <a href="https://doi.org/10.1002/sus2.70046">doi.org/10.1002/sus2.70046</a></li><li>Seul-A Park, Hyeonyeol Jeon, Hojung Kwak, Jun Mo Koo, Dongyeop X. Oh*, and Jeyoung Park*, "High-performance transparent polysulfone nanocomposites enhanced with masterbatch-based aramid nanofibers for improved toughness and flame retardancy," <em>Advanced Composites and Hybrid Materials</em> 8, 307 (2025) <a href="https://doi.org/10.1007/s42114-025-01392-0">doi.org/10.1007/s42114-025-01392-0</a></li><li>Sung Bae Park, Hojung Kwak, Dohoon Lee, Giyoung Shin, Min Jang, Hyuni Jung, Hyeonyeol Jeon*, Hyo Jeong Kim*, Jeyoung Park*, and Dongyeop X. Oh*, "Development of Marine-Degradable Poly(Ester Amide)s with Strong, Up-Scalable, and Up-Cyclable Performance," <em>Advanced Materials</em> 37, 2417266 (2025) <a href="https://doi.org/10.1002/adma.202417266">doi.org/10.1002/adma.202417266</a></li><li>Lam Tan Hao, Sungbin Ju, Dong Ki Hwang, Dong Soo Hwang, Yong Sik Ok, Sung Yeon Hwang, Hyo Jeong Kim, Hyeonyeol Jeon*, Jeyoung Park*, Dongyeop X. Oh*, and Jun Mo Koo*, "Optimizing bioplastics translation," <em>Nature Reviews Bioengineering</em> 2, 289-304 (2024) <a href="https://doi.org/10.1038/s44222-023-00142-5">doi.org/10.1038/s44222-023-00142-5</a></li><li>Minkyung Lee, Hojung Kwak, Youngho Eom, Seul-A Park, Takamasa Sakai, Hyeonyeol Jeon, Jun Mo Koo, Dowan Kim, Chaenyung Cha, Sung Yeon Hwang*, Jeyoung Park*, and Dongyeop X. Oh*, "Network of cyano-p-aramid nanofibres creates ultrastiff and water-rich hydrospongels," <em>Nature Materials</em> 23, 414 (2024) <a href="https://doi.org/10.1038/s41563-023-01760-5">doi.org/10.1038/s41563-023-01760-5</a></li><li>Seon-Mi Kim, Hyeonyeol Jeon, Sung-Ho Shin, Seul-A Park, Jonggeon Jegal, Sung Yeon Hwang*, Dongyeop X. Oh*, and Jeyoung Park*, "Superior toughness and fast self-healing at room temperature engineered by transparent elastomers," <em>Advanced Materials</em> 30, 1705145 (2018) <a href="https://doi.org/10.1002/adma.201705145">doi.org/10.1002/adma.201705145</a></li></ul>$q$,
  research_ko = $q$<p>저희 연구실은 플라스틱 폐기물 없는 사회를 목표로, 고분자의 설계·중합부터 생분해·재활용, 그리고 폐기 이후까지 플라스틱의 전 생애주기에 걸친 지속가능성을 연구합니다.</p><p>지속가능 고분자의 설계와 중합<br>바이오 기반 단량체로 새로운 고분자를 설계·합성하여, 석유계 플라스틱에 버금가는 성능을 갖춘 지속가능 고분자를 개발합니다.</p><p>생분해·재활용·업사이클링<br>생분해성 플라스틱이 실제 토양·퇴비·해양 환경에서 분해되는 거동을 연구하고, 혼합 폐플라스틱을 다시 유용한 고분자로 되돌리는 화학적 재활용·업사이클링 공정을 개발합니다.</p><p>산업바이오·자연계 소재의 산업화<br>산업바이오 공정에서 나오는 단량체와 자연계 물질을 실제 고분자 제품으로 산업화하는 연구를 수행합니다.</p><p>신규 고분자 구조 설계<br>자가치유 고분자, 나노섬유, 나노복합소재 등 새로운 구조의 고분자를 설계하고 다양한 응용으로 연결합니다.</p><p>플라스틱의 전 생애주기(요람에서 무덤까지)<br>소재 설계 단계부터 퇴비화, 생분해, 자원 회수 등 폐기 이후(end-of-life)와 탄소중립을 함께 고려합니다.</p>$q$,
  research_en = $q$<p>Aiming for a society without plastic waste, our laboratory studies sustainability across the whole life cycle of plastics, from polymer design and polymerization to biodegradation, recycling, and what happens after disposal.</p><p>Design and Polymerization of Sustainable Polymers<br>We design and synthesize new polymers from bio-based monomers to develop sustainable polymers whose performance rivals that of petroleum-based plastics.</p><p>Biodegradation, Recycling, and Upcycling<br>We study how biodegradable plastics break down in real soil, compost, and marine environments, and develop chemical recycling and upcycling processes that turn mixed plastic waste back into useful polymers.</p><p>Industrialization of Industrial-Biotechnology and Natural Materials<br>We work on turning monomers from industrial biotechnology processes, and materials found in nature, into real polymer products.</p><p>Design of New Polymer Architectures<br>We design polymers with new architectures, including self-healing polymers, nanofibers, and nanocomposites, and connect them to a range of applications.</p><p>The Whole Life Cycle of Plastics (Cradle to Grave)<br>From the materials-design stage onward, we consider end-of-life pathways such as composting, biodegradation, and resource recovery together with carbon neutrality.</p>$q$,
  lab_url = $q$https://jyp-plastics.com$q$
where name_ko = '박제영';

-- 조현석
update faculty set
  research_ko = $q$<p>PEM 수전해<br>고분자 전해질막(PEM) 수전해는 변동형 그린수소 생산의 주력 기술입니다. 저희는 그 성능을 제한하는 부분, 곧 다공성 수송층과 유로에서 기체와 물이 어떻게 움직이는지, 그리고 실제 운전 조건에서 셀과 스택이 어떻게 열화되는지에 집중합니다(다공성 수송층, 유로 및 2상 유동, 스택 엔지니어링, 산성 OER 촉매 등).</p><p>알칼라인·AEM 수전해<br>알칼라인 수전해는 전 세계 설치 용량의 대부분을 차지하지만, 재생에너지가 아닌 정상 운전을 전제로 만들어졌습니다. 저희는 전극, 분리막, 스택을 그린수소의 변동·간헐 운전 환경에 맞게 다시 설계합니다(변동 운전용 전극, 스택 현상 등).</p><p>CO₂ 전기화학 환원<br>수전해 장치를 작동하게 하는 기술, 곧 기체확산전극, 수송층, 젖음성 제어가 CO₂ 전해로 연료를 실용적인 속도로 만들 수 있는지를 좌우합니다. 저희는 수전해에서 쌓은 기술을 CO₂의 포름산 전환으로 확장합니다(수송층, 계면 기반 선택성 설계 등).</p><p>모델링·진단<br>모델은 단위 셀 측정을 스택 수명 예측과 플랜트 경제성으로 연결합니다. 저희는 물리 기반 전기화학 모델, 열화 진단, 기술경제성 분석을 구축해 실험실과 현장을 잇습니다(물리 기반 셀·스택 모델, 열화 진단, 스케일링 모델 등).</p>$q$,
  research_en = $q$<p>PEM Water Electrolysis<br>Proton exchange membrane electrolysis is the workhorse of dynamic green hydrogen production. We focus on the parts that limit it: how gas and water move through porous transport layers and flow fields, and how cells and stacks degrade under real operating profiles (e.g., porous transport layers, flow fields and two-phase transport, stack engineering, OER catalysts for acidic media).</p><p>Alkaline & AEM Electrolysis<br>Alkaline systems carry most of the world’s installed electrolysis capacity — but they were built for steady operation, not renewables. We re-engineer electrodes, separators, and stacks for the dynamic, intermittent reality of green hydrogen (e.g., electrodes for dynamic operation, stack phenomena).</p><p>CO₂ Electroreduction<br>The same engineering that makes electrolyzers work — gas-diffusion electrodes, transport layers, wetting control — decides whether CO₂ electrolysis can make fuels at practical rates. We carry our electrolysis toolkit into CO₂-to-formate conversion (e.g., transport layers, interface-driven selectivity design).</p><p>Modeling & Diagnostics<br>Models are how single-cell measurements become stack lifetime predictions and plant economics. We build physics-based electrochemical models, degradation diagnostics, and techno-economic analyses that close the loop between the lab and the field (e.g., physics-based cell and stack models, degradation diagnostics, scaling models).</p>$q$,
  keywords = $q$Electrochemical Systems, Electrolyzers, Hydrogen, CO₂ Electroreduction, Corrosion$q$,
  bio_ko = regexp_replace(coalesce(bio_ko,''), '<h3>[^<]*논문[^<]*</h3>.*$', '') || $q$<h3>주요 논문</h3><ul><li>I. Kim, J. Choi, S. Lee, J. Park, C. Lee, J. Seo, J. Kwon, G. Doo, H. Park, D. Lee, W. Cho, C. Kim, N. V. Myung, S. Han, B. An*, M. Kim*, and H. Cho*, "Engineering MnNiPx Cathode via Dual Role of Mn: Simultaneous Enhancement of Activity and Intermittent Operation Durability," <em>Adv. Funct. Mater.</em> 36, e76622 (2026)</li><li>G. Jung, Y. Yun, S. An, D. Kim, M. Sepe, S. Choi, J. Seo, M. Kim, S. Lee, H. Park, S. Shimpalee, H. Kim, C. Lee, G. Doo*, and H. Cho*, "Versatile decal-transfer method for fabricating and analyzing microporous layers in polymer electrolyte membrane water electrolysis," <em>Small</em> 21, 2500086 (2025)</li><li>Y. Yun, J. Choi, Y. Park, H. Park, G. Doo, M. Kim, S. Han, J. Park, S. Lee, C. Lee*, and H. Cho*, "Optimizing Hybrid-phase IrO<sub>2</sub> Catalysts with Ti for Enhanced Oxygen Evolution Reaction for Proton Exchange Membrane Water Electrolysis," <em>Small</em> 21, 2503601 (2025)</li><li>M. Mehdi, B. An, H. Kim, S. Lee, C. Lee, M. Seo, M. Noh, W. Cho, C. Kim, C. Choi, B. Kim, M. Kim, and H. Cho*, "Rational Design of a Stable Fe-rich Ni-Fe Layered Double Hydroxide for the Industrially Relevant Dynamic Operation of Alkaline Water Electrolyzers," <em>Adv. Energy Mater.</em> 13, 2204403 (2023)</li><li>C. Lee, K. Shin, Y. Park, Y. Yun, M. Kim, W. Cho, C. Kim, H. Lee, S. Lee, G. Henkelman, and H. Cho*, "Catalyst-support interaction in Zr<sub>2</sub>ON<sub>2</sub>-supported IrO<sub>x</sub> electrocatalysts to break the trade-off relationship between the activity and stability in the acidic oxygen evolution reaction," <em>Adv. Funct. Mater.</em> 33, 2301557 (2023)</li></ul>$q$,
  bio_en = case when bio_en is null then null else regexp_replace(bio_en, '<h3>[^<]*(논문|Publications?)[^<]*</h3>.*$', '') || $q$<h3>Selected Publications</h3><ul><li>I. Kim, J. Choi, S. Lee, J. Park, C. Lee, J. Seo, J. Kwon, G. Doo, H. Park, D. Lee, W. Cho, C. Kim, N. V. Myung, S. Han, B. An*, M. Kim*, and H. Cho*, "Engineering MnNiPx Cathode via Dual Role of Mn: Simultaneous Enhancement of Activity and Intermittent Operation Durability," <em>Adv. Funct. Mater.</em> 36, e76622 (2026)</li><li>G. Jung, Y. Yun, S. An, D. Kim, M. Sepe, S. Choi, J. Seo, M. Kim, S. Lee, H. Park, S. Shimpalee, H. Kim, C. Lee, G. Doo*, and H. Cho*, "Versatile decal-transfer method for fabricating and analyzing microporous layers in polymer electrolyte membrane water electrolysis," <em>Small</em> 21, 2500086 (2025)</li><li>Y. Yun, J. Choi, Y. Park, H. Park, G. Doo, M. Kim, S. Han, J. Park, S. Lee, C. Lee*, and H. Cho*, "Optimizing Hybrid-phase IrO<sub>2</sub> Catalysts with Ti for Enhanced Oxygen Evolution Reaction for Proton Exchange Membrane Water Electrolysis," <em>Small</em> 21, 2503601 (2025)</li><li>M. Mehdi, B. An, H. Kim, S. Lee, C. Lee, M. Seo, M. Noh, W. Cho, C. Kim, C. Choi, B. Kim, M. Kim, and H. Cho*, "Rational Design of a Stable Fe-rich Ni-Fe Layered Double Hydroxide for the Industrially Relevant Dynamic Operation of Alkaline Water Electrolyzers," <em>Adv. Energy Mater.</em> 13, 2204403 (2023)</li><li>C. Lee, K. Shin, Y. Park, Y. Yun, M. Kim, W. Cho, C. Kim, H. Lee, S. Lee, G. Henkelman, and H. Cho*, "Catalyst-support interaction in Zr<sub>2</sub>ON<sub>2</sub>-supported IrO<sub>x</sub> electrocatalysts to break the trade-off relationship between the activity and stability in the acidic oxygen evolution reaction," <em>Adv. Funct. Mater.</em> 33, 2301557 (2023)</li></ul>$q$ end
where name_ko = '조현석';

select name_ko, title_ko, lab_ko, lab_url, building, room, keywords, scholar_url, length(bio_ko) bio_ko, length(bio_en) bio_en, length(research_ko) res_ko, length(research_en) res_en
from faculty where name_ko in ('이종석', '강문성', '류재건', '이성현', '김충익', '박제영', '조현석') order by name_ko;
